<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Conway's Game of Life</title>
    <style>
        :root {
            --bg: #0a0a14;
            --surface: #12122a;
            --canvas-bg: #181830;
            --accent: #00e676;
            --accent-glow: rgba(0, 230, 118, 0.45);
            --accent-strong: #69f0ae;
            --text: #e0e0e0;
            --text-muted: #8888aa;
            --btn-bg: #1e1e3a;
            --btn-border: #2a2a50;
            --btn-hover-bg: #282850;
            --btn-active-bg: #00c853;
            --btn-active-text: #0a0a14;
            --radius: 28px;
            --radius-sm: 10px;
            --shadow-glow: 0 0 30px rgba(0, 230, 118, 0.25);
            --transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background: var(--bg);
            display: flex;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
            font-family: 'Segoe UI', 'Inter', system-ui, -apple-system, sans-serif;
            user-select: none;
            -webkit-user-select: none;
            -webkit-tap-highlight-color: transparent;
            overflow-x: hidden;
        }

        .container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 22px;
            padding: 20px;
        }

        .canvas-wrapper {
            background: var(--surface);
            border-radius: 16px;
            padding: 12px;
            box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5), var(--shadow-glow);
            transition: box-shadow var(--transition);
            position: relative;
        }

        .canvas-wrapper.running {
            box-shadow: 0 8px 50px rgba(0, 0, 0, 0.55), 0 0 50px rgba(0, 230, 118, 0.35);
        }

        #life {
            display: block;
            border-radius: 8px;
            cursor: crosshair;
            background: var(--canvas-bg);
            touch-action: none;
            image-rendering: auto;
        }

        .controls {
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
            justify-content: center;
            align-items: center;
        }

        .btn {
            padding: 12px 24px;
            border: 2px solid var(--btn-border);
            background: var(--btn-bg);
            color: var(--text);
            border-radius: var(--radius);
            cursor: pointer;
            font-size: 15px;
            font-weight: 600;
            letter-spacing: 0.4px;
            transition: all var(--transition);
            outline: none;
            position: relative;
            overflow: hidden;
            white-space: nowrap;
            min-width: 80px;
            text-align: center;
        }

        .btn:hover {
            background: var(--btn-hover-bg);
            border-color: #3a3a65;
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.35);
        }

        .btn:active {
            transform: translateY(0);
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
            transition: all 0.08s;
        }

        .btn.accent {
            border-color: var(--accent);
            color: var(--accent);
            background: rgba(0, 230, 118, 0.06);
        }

        .btn.accent:hover {
            background: rgba(0, 230, 118, 0.14);
            border-color: var(--accent-strong);
            box-shadow: 0 6px 24px rgba(0, 230, 118, 0.2);
        }

        .btn.accent.active {
            background: var(--btn-active-bg);
            color: var(--btn-active-text);
            border-color: var(--btn-active-bg);
            font-weight: 700;
            animation: pulse-glow 1.8s ease-in-out infinite;
            box-shadow: 0 4px 24px rgba(0, 230, 118, 0.4);
        }

        @keyframes pulse-glow {
            0%,
            100% {
                box-shadow: 0 4px 24px rgba(0, 230, 118, 0.4);
            }
            50% {
                box-shadow: 0 4px 38px rgba(0, 230, 118, 0.7), 0 0 60px rgba(0, 230, 118, 0.3);
            }
        }

        .btn.accent.active:hover {
            background: #00e676;
            border-color: #00e676;
            box-shadow: 0 6px 32px rgba(0, 230, 118, 0.55);
        }

        .status-row {
            display: flex;
            align-items: center;
            gap: 10px;
            color: var(--text-muted);
            font-size: 13px;
            font-weight: 500;
            letter-spacing: 0.3px;
            height: 20px;
        }

        .status-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: #555;
            transition: all var(--transition);
        }

        .status-dot.live {
            background: var(--accent);
            box-shadow: 0 0 10px var(--accent-glow);
        }

        @media (max-width: 540px) {
            #life {
                width: 94vw !important;
                height: 94vw !important;
            }
            .btn {
                padding: 10px 16px;
                font-size: 13px;
                min-width: 60px;
                border-radius: 22px;
            }
            .controls {
                gap: 8px;
            }
            .container {
                gap: 14px;
                padding: 12px;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="canvas-wrapper" id="canvasWrapper">
            <canvas id="life"></canvas>
        </div>
        <div class="controls">
            <button class="btn" id="step" title="Advance one generation">Step</button>
            <button class="btn accent" id="play" title="Toggle auto-run">▶ Play</button>
            <button class="btn" id="random" title="Seed random cells">Random</button>
            <button class="btn" id="clear" title="Kill all cells">Clear</button>
        </div>
        <div class="status-row">
            <span class="status-dot" id="statusDot"></span>
            <span id="statusLabel">Ready — paint cells or press Play</span>
        </div>
    </div>

    <script>
        (function() {
            // ─────────────────────────────────────
            // Grid & Canvas Setup
            // ─────────────────────────────────────
            const W = 50;
            const H = 50;
            const CANVAS_SIZE = 500; // CSS pixels
            const CELL_SIZE = CANVAS_SIZE / W; // 10px per cell
            const GAP = 1; // 1px gap between cells
            const CELL_DRAW_SIZE = CELL_SIZE - GAP * 2; // 8px drawn cell

            const canvas = document.getElementById('life');
            const ctx = canvas.getContext('2d');
            const wrapper = document.getElementById('canvasWrapper');
            const statusDot = document.getElementById('statusDot');
            const statusLabel = document.getElementById('statusLabel');

            // Set canvas internal resolution and CSS size
            canvas.width = CANVAS_SIZE;
            canvas.height = CANVAS_SIZE;
            canvas.style.width = CANVAS_SIZE + 'px';
            canvas.style.height = CANVAS_SIZE + 'px';

            // ─────────────────────────────────────
            // Grid buffers (flat arrays for performance)
            // ─────────────────────────────────────
            let grid = new Uint8Array(W * H);
            let nextGrid = new Uint8Array(W * H);

            // ─────────────────────────────────────
            // Rendering
            // ─────────────────────────────────────
            const DEAD_COLOR = '#181830';
            const ALIVE_COLOR = '#00f060';
            const GLOW_COLOR = 'rgba(0, 240, 96, 0.55)';

            function render() {
                ctx.clearRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

                // Fill background
                ctx.fillStyle = DEAD_COLOR;
                ctx.fillRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

                // Count live cells for status
                let liveCount = 0;

                // Draw live cells with glow
                ctx.fillStyle = ALIVE_COLOR;
                ctx.shadowBlur = 5;
                ctx.shadowColor = GLOW_COLOR;

                for (let y = 0; y < H; y++) {
                    for (let x = 0; x < W; x++) {
                        if (grid[y * W + x] === 1) {
                            liveCount++;
                            const px = x * CELL_SIZE + GAP;
                            const py = y * CELL_SIZE + GAP;
                            ctx.fillRect(px, py, CELL_DRAW_SIZE, CELL_DRAW_SIZE);
                        }
                    }
                }

                // Reset shadow
                ctx.shadowBlur = 0;
                ctx.shadowColor = 'transparent';

                // Update status
                updateStatus(liveCount);
            }

            function updateStatus(liveCount) {
                if (liveCount > 0) {
                    statusDot.classList.add('live');
                } else {
                    statusDot.classList.remove('live');
                }
                if (running) {
                    statusLabel.textContent = `Running — ${liveCount} live cell${liveCount !== 1 ? 's' : ''}`;
                } else if (liveCount > 0) {
                    statusLabel.textContent = `Paused — ${liveCount} live cell${liveCount !== 1 ? 's' : ''}`;
                } else {
                    statusLabel.textContent = 'Ready — paint cells or press Play';
                }
            }

            // ─────────────────────────────────────
            // Simulation Logic (simultaneous update)
            // ─────────────────────────────────────
            function countNeighbors(g, x, y) {
                let count = 0;
                // Top row
                if (y > 0) {
                    if (x > 0 && g[(y - 1) * W + (x - 1)] === 1) count++;
                    if (g[(y - 1) * W + x] === 1) count++;
                    if (x < W - 1 && g[(y - 1) * W + (x + 1)] === 1) count++;
                }
                // Middle row (left & right)
                if (x > 0 && g[y * W + (x - 1)] === 1) count++;
                if (x < W - 1 && g[y * W + (x + 1)] === 1) count++;
                // Bottom row
                if (y < H - 1) {
                    if (x > 0 && g[(y + 1) * W + (x - 1)] === 1) count++;
                    if (g[(y + 1) * W + x] === 1) count++;
                    if (x < W - 1 && g[(y + 1) * W + (x + 1)] === 1) count++;
                }
                return count;
            }

            function computeNextGeneration() {
                for (let y = 0; y < H; y++) {
                    for (let x = 0; x < W; x++) {
                        const idx = y * W + x;
                        const alive = grid[idx] === 1;
                        const neighbors = countNeighbors(grid, x, y);

                        if (alive) {
                            // Survival: 2 or 3 neighbors
                            nextGrid[idx] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
                        } else {
                            // Birth: exactly 3 neighbors
                            nextGrid[idx] = (neighbors === 3) ? 1 : 0;
                        }
                    }
                }
                // Swap buffers
                const temp(a) = grid;
                grid = nextGrid;
                nextGrid = temp;
            }

            function stepSimulation() {
                computeNextGeneration();
                render();
            }

            function clearGrid() {
                grid.fill(0);
                nextGrid.fill(0);
                render();
            }

            function seedRandom(density = 0.32) {
                for (let i = 0; i < W * H; i++) {
                    grid[i] = Math.random() < density ? 1 : 0;
                }
                nextGrid.fill(0);
                render();
            }

            // ─────────────────────────────────────
            // Auto-run
            // ─────────────────────────────────────
            let running = false;
            let runInterval = null;
            const RUN_SPEED = 110; // ms per generation

            const playBtn = document.getElementById('play');

            function startAutoRun() {
                if (running) return;
                running = true;
                playBtn.textContent = '⏸ Pause';
                playBtn.classList.add('active');
                wrapper.classList.add('running');
                statusLabel.textContent = 'Running…';
                runInterval = setInterval(stepSimulation, RUN_SPEED);
            }

            function stopAutoRun() {
                if (!running) return;
                running = false;
                playBtn.textContent = '▶ Play';
                playBtn.classList.remove('active');
                wrapper.classList.remove('running');
                if (runInterval) {
                    clearInterval(runInterval);
                    runInterval = null;
                }
                // Re-render to update status label
                render();
            }

            function toggleAutoRun() {
                if (running) {
                    stopAutoRun();
                } else {
                    startAutoRun();
                }
            }

            // ─────────────────────────────────────
            // Mouse & Touch Painting
            // ─────────────────────────────────────
            let isPainting = false;
            let paintMode = null; // true = paint alive, false = paint dead
            let lastPaintedIdx = -1;

            function getCellFromEvent(e) {
                const rect = canvas.getBoundingClientRect();
                const scaleX = CANVAS_SIZE / rect.width;
                const scaleY = CANVAS_SIZE / rect.height;
                const mx = (e.clientX - rect.left) * scaleX;
                const my = (e.clientY - rect.top) * scaleY;
                const cx = Math.floor(mx / CELL_SIZE);
                const cy = Math.floor(my / CELL_SIZE);
                if (cx < 0 || cx >= W || cy < 0 || cy >= H) return null;
                return { x: cx, y: cy, idx: cy * W + cx };
            }

            function getCellFromTouch(touch) {
                const rect = canvas.getBoundingClientRect();
                const scaleX = CANVAS_SIZE / rect.width;
                const scaleY = CANVAS_SIZE / rect.height;
                const mx = (touch.clientX - rect.left) * scaleX;
                const my = (touch.clientY - rect.top) * scaleY;
                const cx = Math.floor(mx / CELL_SIZE);
                const cy = Math.floor(my / CELL_SIZE);
                if (cx < 0 || cx >= W || cy < 0 || cy >= H) return null;
                return { x: cx, y: cy, idx: cy * W + cx };
            }

            function paintCell(cell) {
                if (cell === null) return false;
                if (cell.idx === lastPaintedIdx) return false;
                const currentVal = grid[cell.idx];
                const desiredVal = paintMode ? 1 : 0;
                if (currentVal === desiredVal) {
                    lastPaintedIdx = cell.idx;
                    return false; // no change needed
                }
                grid[cell.idx] = desiredVal;
                lastPaintedIdx = cell.idx;
                return true;
            }

            canvas.addEventListener('mousedown', function(e) {
                if (e.button !== 0) return; // left button only
                const cell = getCellFromEvent(e);
                if (cell === null) return;
                isPainting = true;
                // Toggle the cell: flip its state
                const currentVal = grid[cell.idx];
                paintMode = currentVal === 0; // if dead -> paint alive; if alive -> paint dead
                grid[cell.idx] = paintMode ? 1 : 0;
                lastPaintedIdx = cell.idx;
                render();
                e.preventDefault();
            });

            canvas.addEventListener('mousemove', function(e) {
                if (!isPainting) return;
                const cell = getCellFromEvent(e);
                if (paintCell(cell)) {
                    render();
                }
                e.preventDefault();
            });

            window.addEventListener('mouseup', function(e) {
                if (isPainting) {
                    isPainting = false;
                    paintMode = null;
                    lastPaintedIdx = -1;
                }
            });

            canvas.addEventListener('mouseleave', function(e) {
                if (isPainting) {
                    isPainting = false;
                    paintMode = null;
                    lastPaintedIdx = -1;
                }
            });

            // Touch events
            canvas.addEventListener('touchstart', function(e) {
                if (e.touches.length !== 1) return;
                const cell = getCellFromTouch(e.touches[0]);
                if (cell === null) return;
                isPainting = true;
                const currentVal = grid[cell.idx];
                paintMode = currentVal === 0;
                grid[cell.idx] = paintMode ? 1 : 0;
                lastPaintedIdx = cell.idx;
                render();
                e.preventDefault();
            }, { passive: false });

            canvas.addEventListener('touchmove', function(e) {
                if (!isPainting || e.touches.length !== 1) return;
                const cell = getCellFromTouch(e.touches[0]);
                if (paintCell(cell)) {
                    render();
                }
                e.preventDefault();
            }, { passive: false });

            canvas.addEventListener('touchend', function(e) {
                isPainting = false;
                paintMode = null;
                lastPaintedIdx = -1;
            });

            canvas.addEventListener('touchcancel', function(e) {
                isPainting = false;
                paintMode = null;
                lastPaintedIdx = -1;
            });

            // ─────────────────────────────────────
            // Button Handlers
            // ─────────────────────────────────────
            document.getElementById('step').addEventListener('click', function() {
                stepSimulation();
            });

            playBtn.addEventListener('click', function() {
                toggleAutoRun();
            });

            document.getElementById('random').addEventListener('click', function() {
                seedRandom();
            });

            document.getElementById('clear').addEventListener('click', function() {
                if (running) stopAutoRun();
                clearGrid();
            });

            // ─────────────────────────────────────
            // Keyboard shortcuts
            // ─────────────────────────────────────
            window.addEventListener('keydown', function(e) {
                switch (e.key.toLowerCase()) {
                    case ' ':
                        e.preventDefault();
                        toggleAutoRun();
                        break;
                    case 's':
                        if (!e.ctrlKey && !e.metaKey && !e.altKey) {
                            e.preventDefault();
                            stepSimulation();
                        }
                        break;
                    case 'r':
                        if (!e.ctrlKey && !e.metaKey && !e.altKey && document.activeElement === document.body) {
                            e.preventDefault();
                            seedRandom();
                        }
                        break;
                    case 'c':
                        if (!e.ctrlKey && !e.metaKey && !e.altKey && document.activeElement === document.body) {
                            e.preventDefault();
                            if (running) stopAutoRun();
                            clearGrid();
                        }
                        break;
                }
            });

            // ─────────────────────────────────────
            // Programmatic API (window.life)
            // ─────────────────────────────────────
            window.life = {
                w: W,
                h: H,

                get: function(x, y) {
                    if (x < 0 || x >= W || y < 0 || y >= H) return 0;
                    return grid[y * W + x];
                },

                set: function(x, y, v) {
                    if (x < 0 || x >= W || y < 0 || y >= H) return;
                    grid[y * W + x] = v ? 1 : 0;
                    // Note: no automatic redraw here (for efficient batch seeding by grading)
                },

                step: function() {
                    stepSimulation();
                },

                clear: function() {
                    clearGrid();
                },
            };

            // ─────────────────────────────────────
            // Initial Render
            // ─────────────────────────────────────
            render();

            console.log('%c🐣 Conway\'s Game of Life %cready',
                'color: #00e676; font-size: 16px; font-weight: bold;',
                'color: #aaa;');
            console.log('%c  Grid: %c' + W + '×' + H + ' %c| %cCanvas: %c' + CANVAS_SIZE + '×' + CANVAS_SIZE +
                ' CSS px',
                'color: #888;', 'color: #fff;', 'color: #888;', 'color: #888;', 'color: #fff;');
            console.log('%c  API: %cwindow.life %c{ w, h, get, set, step, clear }',
                'color: #888;', 'color: #69f0ae;', 'color: #aaa;');
            console.log('%c  Shortcuts: %c[Space] %cplay/pause %c| %c[S] %cstep %c| %c[R] %crandom %c| %c[C] %cclear',
                'color: #888;', 'color: #ff0;', 'color: #aaa;',
                'color: #888;', 'color: #ff0;', 'color: #aaa;',
                'color: #888;', 'color: #ff0;', 'color: #aaa;',
                'color: #888;', 'color: #ff0;', 'color: #aaa;');
        })();
    </script>
</body>
</html>
